                    cr, cc = queue.pop(0)
                    region.append((cr, cc))
                    if cr == 0 or cr == len(demo_in)-1 or cc == 0 or cc == len(demo_in[0])-1:
                        boundary_touching = True
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
