                if len(output_region) == len(region):
                    print(f"  KEPT: {len(region)} cells, touches boundary={boundary_touching}")
                elif len(output_region) == 0:
                    print(f"  REMOVED: {len(region)} cells, touches boundary={boundary_touching}")
